# Generated by rarpar-bench fleet. Do not edit on the host.
$ErrorActionPreference = 'Continue'
$ProgressPreference = 'SilentlyContinue'
$RunId = 'fleet-testrun'
$MachineName = 'win-dgpu'
$Base = 'C:\bench\fleet-stage\fleet-testrun'
$Bin = 'C:\bench\fleet-stage\fleet-testrun\bin'
$R = 'C:\bench\fleet-stage\fleet-testrun\results'
$W = 'C:\bench\work\fleet-testrun'
$Machine = 'windows-x86_64-zen4'
$Corpus = 'C:\bench\corpus'
$Zip = 'C:\bench\fleet-stage\fleet-testrun\results.zip'
$Done = 'C:\bench\fleet-stage\fleet-testrun\DONE'
$Bench = Join-Path $Bin 'rarpar-bench.exe'
$Candidate = Join-Path $Bin 'rarpar.exe'
$OracleRar = 'C:\bench\oracles\UnRAR.exe'
$OraclePar2 = ''
$OraclePar3 = 'C:\bench\fleet-stage\fleet-testrun\oracles\par3.exe'
$Utf8NoBom = New-Object Text.UTF8Encoding $false
$Status = 'ok'
$Failures = @()
$Started = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
$StartTicks = [DateTime]::UtcNow
foreach ($d in @($R, $W)) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Force -Path $d | Out-Null } }
$env:RARPAR_BENCH_WORKSPACE_ROOT = $Base
function Log($m) { Write-Output ("[{0}] {1}" -f (Get-Date).ToUniversalTime().ToString('HH:mm:ss'), $m) }
function Fail($m) { $script:Status = 'failed'; $script:Failures += $m; Log "FAILURE: $m" }
function Check($what) { if ($LASTEXITCODE -ne 0) { Fail ($what + ':exit-' + $LASTEXITCODE) } }
function Gate($what) {
  $names = @('rarpar-bench','rarpar','par2','unrar','decode_timing','searchend_timing','crc_probe')
  $waited = 0
  while ($true) {
    $busy = @()
    foreach ($n in $names) { if (Get-Process -Name $n -ErrorAction SilentlyContinue) { $busy += $n } }
    if ($busy.Count -eq 0) { Log "GATE $what clear (waited ${waited}s)"; return }
    if ($waited -ge 900) { Log "GATE $what proceeding after ${waited}s"; return }
    Log "GATE $what busy: $($busy -join ',')"
    Start-Sleep -Seconds 30; $waited += 30
  }
}
Get-ComputerInfo | Out-File -LiteralPath (Join-Path $R 'environment.txt') -Encoding utf8
Get-ChildItem -LiteralPath $Bin | Out-File -LiteralPath (Join-Path $R 'binaries.txt') -Encoding utf8
Get-ChildItem -LiteralPath $Bin -File | ForEach-Object { Get-FileHash -Algorithm SHA256 -LiteralPath $_.FullName } | Out-File -LiteralPath (Join-Path $R 'binaries.txt') -Append -Encoding utf8
$probe = Join-Path $Bin 'crc_probe.exe'
if (Test-Path -LiteralPath $probe) { Gate 'crc-probe'; & $probe *> (Join-Path $R 'crc_probe.txt'); Check 'crc-probe' } else { Fail 'crc-probe-binary-missing' }
& $Bench corpus verify --root $Corpus *> (Join-Path $R 'corpus-verify.txt')
Check 'corpus-verify'
$plan = Join-Path $W 'plan-rar.json'
& $Bench plan create --corpus $Corpus --out $plan --seed 'rarpar-benchmark-plan-v1' --lane 'cpu' --family 'rar' --par2-placement 'canonical' --warmups 1 --repeats 7 *> (Join-Path $R 'plan-rar.log')
Check 'plan-rar'
Copy-Item -LiteralPath $plan -Destination (Join-Path $R 'plan-rar.json') -ErrorAction SilentlyContinue
Gate 'rar'
$out = Join-Path $W 'run-rar'
if (Test-Path -LiteralPath $out) { Remove-Item -LiteralPath $out -Recurse -Force -ErrorAction SilentlyContinue }
$benchArgs = @('run','--corpus',$Corpus,'--plan',$plan,'--candidate',$Candidate,'--candidate-label','rarpar','--reference-label','reference','--out',$out,'--machine',$Machine)
if ($OracleRar) { $benchArgs += @('--reference-rar', $OracleRar) }
if ($OraclePar2) { $benchArgs += @('--reference-par2', $OraclePar2) }
& $Bench @benchArgs *> (Join-Path $R 'run-rar.log')
Check 'run-rar'
Copy-Item -LiteralPath (Join-Path $out 'raw.json') -Destination (Join-Path $R 'raw-rar.json') -ErrorAction SilentlyContinue
& $Bench report --input (Join-Path $out 'raw.json') --out (Join-Path $R 'report-rar.json') *> (Join-Path $R 'report-rar.log')
Check 'report-rar'
if (Test-Path -LiteralPath $out) { Remove-Item -LiteralPath $out -Recurse -Force -ErrorAction SilentlyContinue }
$p3Work = 'C:\p3'
if (Test-Path -LiteralPath $OraclePar3) {
  Gate 'macro-par3'
  $p3Args = @('par3','run','--reference',$OraclePar3,'--candidate',$Candidate,'--work',$p3Work,'--out',(Join-Path $R 'par3'),'--machine',$Machine,'--profile','full','--workers','1,8','--warmups','1','--repeats','5','--timeout','20m')
  & $Bench @p3Args *> (Join-Path $R 'par3-run.log')
  Check 'macro-par3'
} else { Fail 'par3-reference-missing' }
if (Test-Path -LiteralPath $p3Work) { Remove-Item -LiteralPath $p3Work -Recurse -Force -ErrorAction SilentlyContinue }
[IO.File]::WriteAllText((Join-Path $R 'perf-NO-COLLECTOR.txt'), "capabilities.perf = none on Windows hosts; phase timings only`r`n", $Utf8NoBom)
$Finished = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
$Elapsed = [int]([DateTime]::UtcNow - $StartTicks).TotalSeconds
$RFull = (Get-Item -LiteralPath $R).FullName.TrimEnd('\')
$files = Get-ChildItem -LiteralPath $R -Recurse -File | Where-Object { $_.Name -ne 'MANIFEST.json' } | ForEach-Object {
  [ordered]@{ path = $_.FullName.Substring($RFull.Length + 1).Replace('\','/'); bytes = $_.Length; sha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $_.FullName).Hash.ToLower() } }
$manifest = [ordered]@{ schema_version = 1; run_id = $RunId; machine = $MachineName; platform_label = $Machine; started_utc = $Started; finished_utc = $Finished; elapsed_seconds = $Elapsed; status = $Status; failures = ($Failures -join ' '); files = @($files) }
[IO.File]::WriteAllText((Join-Path $R 'MANIFEST.json'), ($manifest | ConvertTo-Json -Depth 5), $Utf8NoBom)
Add-Type -AssemblyName System.IO.Compression.FileSystem
if (Test-Path -LiteralPath $Zip) { Remove-Item -LiteralPath $Zip -Force }
[IO.Compression.ZipFile]::CreateFromDirectory($R, $Zip)
$zipHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $Zip).Hash.ToLower()
$zipBytes = (Get-Item -LiteralPath $Zip).Length
$sentinel = @(('status=' + $Status), ('run_id=' + $RunId), ('machine=' + $MachineName), ('started_utc=' + $Started), ('finished_utc=' + $Finished), ('elapsed_seconds=' + $Elapsed), ('tarball=' + $Zip), ('tarball_sha256=' + $zipHash), ('tarball_bytes=' + $zipBytes), ('files=' + @($files).Count), ('failures=' + ($Failures -join ' '))) -join "`r`n"
[IO.File]::WriteAllText(($Done + '.tmp'), ($sentinel + "`r`n"), $Utf8NoBom)
Move-Item -LiteralPath ($Done + '.tmp') -Destination $Done -Force
Log "RUN COMPLETE status=$Status elapsed=${Elapsed}s"
